/**
 * The Java type that carries a value of the named Fortress type, or null.  FortressLibrary's traits
 * JavaBufferedWriter and JavaBufferedReader, names that no program can give its own types, are
 * carried by their names in the compiled run time's FortressBufferedWriter and FortressBufferedReader,
 * which walk's values JavaBufferedWriterObject.Value and JavaBufferedReaderObject.Value hold.
 */
static Class<?> javaFor(String t) {
    if (t == null) return null;
    if (t.equals("ZZ32") || t.equals("NN32") || t.equals("Char")) return int.class;
    if (t.equals("ZZ64") || t.equals("NN64")) return long.class;
    if (t.equals("RR64") || t.equals("Float")) return double.class;
    if (t.equals("RR32")) return float.class;
    if (t.equals("Boolean")) return boolean.class;
    if (t.equals("String") || t.equals("FlatString") || t.equals("JavaString")) return String.class;
    if (t.equals("ZZ")) return BigInteger.class;
    if (t.equals("()")) return void.class;
    if (t.equals("JavaBufferedWriter")) return FortressBufferedWriter.class;
    if (t.equals("JavaBufferedReader")) return FortressBufferedReader.class;
    return null;
}

/**
 * The Java type that carries an argument of the named declared parameter type, or null: as javaFor,
 * except that no Java type carries a parameter declared String, whose value can be a string that is
 * not flat, whose characters the loader cannot take.  A result declared String is carried, as a
 * flat string.
 */
static Class<?> javaForParameter(String t) {
    return "String".equals(t) ? null : javaFor(t);
}

